import {loadReportPages,filterReport,reportTime} from './report-data.js';
import {statusLabel} from './report-metrics.js';
import {reportSignature,signatureImage} from './report-signatures.js';
export const MAX_SIGNATURE_REPORT_ROWS=200;
export const orderedReport=(items,filters)=>filterReport(items,filters).sort((a,b)=>(b.createdAtMs??-Infinity)-(a.createdAtMs??-Infinity)||a.id.localeCompare(b.id));
export function reportFingerprint(items,event={}){return JSON.stringify([event,[...items].sort((a,b)=>a.id.localeCompare(b.id)).map(r=>[r.id,r.referenceCode,r.participantName,r.status,r.checkedIn,r.createdAtMs,r.checkedInAtMs,!!r.hasSignature,r.signatureHash])])}
export async function prepareSignatureReport(client,eventId,filters,isCurrent,onProgress=()=>{}){
 let event={id:eventId,name:eventId},completed=0;
 const items=await loadReportPages(client,eventId,isCurrent,()=>{},data=>event=data);if(items===null)return null;
 const rows=orderedReport(items,filters);if(!rows.length)throw new Error('ไม่มีรายการตามตัวกรองนี้');if(rows.length>MAX_SIGNATURE_REPORT_ROWS)throw new Error('รายงานพร้อมลายเซ็นรองรับครั้งละไม่เกิน 200 รายการ กรุณาลดช่วงวันที่หรือเลือกสถานะก่อนพิมพ์');
 const signed=rows.filter(r=>r.hasSignature),signatures=new Map();let cursor=0,failure;onProgress(0,signed.length);
 await Promise.all(Array.from({length:Math.min(3,signed.length)},async()=>{while(cursor<signed.length&&isCurrent()&&!failure){const row=signed[cursor++];try{const data=await reportSignature(client,eventId,row,isCurrent);signatures.set(row.id,data);onProgress(++completed,signed.length)}catch(error){failure=error}}}));
 if(!isCurrent())return null;if(failure)throw failure;
 const snapshot={event,rows,signatures,filters:{...filters},generatedAt:Date.now()};await verifySignatureReport(client,eventId,snapshot,isCurrent);return isCurrent()?snapshot:null;
}
export async function verifySignatureReport(client,eventId,snapshot,isCurrent){let event=snapshot.event;const current=await loadReportPages(client,eventId,isCurrent,()=>{},data=>event=data);if(current===null)return false;if(reportFingerprint(orderedReport(current,snapshot.filters),event)!==reportFingerprint(snapshot.rows,snapshot.event))throw new Error('ข้อมูลรายงานเปลี่ยนระหว่างโหลด กรุณากดโหลดรายงานพร้อมลายเซ็นใหม่');return true}
export function renderSignatureSheet(root,snapshot){
 root.replaceChildren();const heading=document.createElement('header');heading.className='signature-sheet-heading';const school=document.createElement('p'),title=document.createElement('h1'),event=document.createElement('h2');school.textContent='โรงเรียนสาธิตแห่งมหาวิทยาลัยเกษตรศาสตร์ วิทยาเขตกำแพงแสน';title.textContent='รายงานผู้เข้าร่วมกิจกรรมและลายเซ็น';event.textContent=snapshot.event.name;heading.append(school,title,event);
 for(const text of [snapshot.event.date?'วันจัดกิจกรรม: '+snapshot.event.date:'',snapshot.event.place?'สถานที่: '+snapshot.event.place:'','ตัวกรอง: '+filterDescription(snapshot.filters),'จัดทำเมื่อ '+new Date(snapshot.generatedAt).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})+' · '+snapshot.rows.length+' รายการ · เช็คอิน '+snapshot.rows.filter(r=>r.checkedIn).length+' คน · มีลายเซ็น '+snapshot.signatures.size+' คน']){if(text){const p=document.createElement('p');p.textContent=text;heading.append(p)}}root.append(heading);
 const table=document.createElement('table');table.className='signature-sheet-table';table.innerHTML='<colgroup><col style="width:6%"><col style="width:28%"><col style="width:14%"><col style="width:22%"><col style="width:30%"></colgroup><thead><tr><th>ลำดับ</th><th>ชื่อ–นามสกุล / เลขอ้างอิง</th><th>สถานะสมัคร</th><th>เช็คอิน (เวลาไทย)</th><th>ลายเซ็นผู้เข้าร่วม</th></tr></thead>';const body=document.createElement('tbody');
 snapshot.rows.forEach((row,index)=>{const tr=document.createElement('tr');const cells=Array.from({length:5},()=>{const td=document.createElement('td');tr.append(td);return td});cells[0].textContent=String(index+1);const name=document.createElement('strong'),ref=document.createElement('small');name.textContent=row.participantName;ref.textContent=row.referenceCode||row.id;cells[1].append(name,ref);cells[2].textContent=statusLabel[row.status]||row.status;cells[3].textContent=row.checkedIn?reportTime(row.checkedInAtMs):'ยังไม่เช็คอิน';const signature=snapshot.signatures.get(row.id);if(signature){cells[4].append(signatureImage(signature,{lazy:false}));const time=document.createElement('small');time.textContent=(signature.signerName!==row.participantName?'ผู้ลงนาม: '+signature.signerName+' · ':'')+'บันทึก '+reportTime(signature.recordedAtMs);cells[4].append(time)}else cells[4].textContent='ยังไม่มีลายเซ็น';body.append(tr)});table.append(body);root.append(table);const foot=document.createElement('p');foot.className='signature-sheet-footnote';foot.textContent='ข้อมูลตามสถานะ ณ เวลาจัดทำรายงาน · ไม่รวมใบสมัครในถังขยะ · ลายเซ็นเป็นภาพที่บันทึกผ่านจุดเช็คอิน';root.append(foot);
}
export function filterDescription({from='',to='',status='all',checkin='all'}={}){return ['วันที่สมัคร '+(from||'ไม่จำกัด')+' ถึง '+(to||'ไม่จำกัด'),status==='all'?'ทุกสถานะ':statusLabel[status]||status,checkin==='yes'?'เฉพาะเช็คอินแล้ว':checkin==='no'?'เฉพาะยังไม่เช็คอิน':'ทั้งเช็คอินและยังไม่เช็คอิน'].join(' · ')}
async function imageReady(root){await Promise.all([...root.querySelectorAll('img')].map(img=>typeof img.decode==='function'?img.decode():new Promise((resolve,reject)=>{if(img.complete)return img.naturalWidth?resolve():reject(Error('โหลดภาพไม่สำเร็จ'));img.onload=resolve;img.onerror=()=>reject(Error('โหลดภาพไม่สำเร็จ'))})))}
export async function openSignatureReport(client,eventId,filters,parentCurrent=()=>true,{waitImages=imageReady,print=()=>window.print()}={}){
 const dialog=document.createElement('dialog');dialog.id='signature-report';dialog.setAttribute('aria-label','รายงานพร้อมลายเซ็น');const controls=document.createElement('div');controls.className='signature-report-controls';const title=document.createElement('h2'),status=document.createElement('p'),printButton=document.createElement('button'),retry=document.createElement('button'),close=document.createElement('button');title.textContent='รายงานพร้อมลายเซ็น';status.setAttribute('role','status');printButton.type=retry.type=close.type='button';printButton.className='primary';printButton.textContent='พิมพ์ / บันทึก PDF';retry.textContent='โหลดรายงานใหม่';close.textContent='ปิด';const note=document.createElement('p');note.className='sub';note.textContent='พิมพ์ A4 แนวตั้ง หรือเลือก “บันทึกเป็น PDF” ในหน้าพิมพ์ของอุปกรณ์';controls.append(title,status,printButton,retry,close,note);const sheet=document.createElement('article');sheet.className='signature-report-sheet';const printOutput=document.createElement('section');printOutput.id='signature-print-output';printOutput.hidden=true;printOutput.textContent='รายงานยังไม่พร้อมพิมพ์ กรุณารอให้โหลดข้อมูลและลายเซ็นครบก่อน';dialog.append(controls,sheet);document.body.append(dialog,printOutput);document.body.classList.add('signature-print-open');dialog.showModal();close.focus();let closed=false,snapshot=null,busy=false;
 const active=()=>!closed&&parentCurrent()&&dialog.isConnected&&dialog.open;
 function dispose(){if(closed)return;closed=true;document.body.classList.remove('signature-print-open');observer.disconnect();window.removeEventListener('hashchange',route);dialog.replaceChildren();printOutput.replaceChildren();printOutput.remove();dialog.remove()}
 const route=()=>{if(!parentCurrent()){dialog.close();dispose()}},observer=new MutationObserver(route);observer.observe(document.body,{subtree:true,childList:true});window.addEventListener('hashchange',route);dialog.addEventListener('close',dispose,{once:true});close.onclick=()=>dialog.close();
 async function load(){if(busy||!active())return;busy=true;snapshot=null;delete dialog.dataset.printReady;printOutput.textContent='รายงานยังไม่พร้อมพิมพ์ กรุณารอให้โหลดข้อมูลและลายเซ็นครบก่อน';printButton.disabled=retry.disabled=true;sheet.replaceChildren();status.textContent='กำลังโหลดข้อมูลล่าสุดและลายเซ็น…';try{const data=await prepareSignatureReport(client,eventId,filters,active,(done,total)=>{if(active())status.textContent='กำลังโหลดลายเซ็น '+done+' / '+total+' รายการ…'});if(!data||!active())return;renderSignatureSheet(sheet,data);await waitImages(sheet);if(!active())return;snapshot=data;printOutput.replaceChildren(sheet.cloneNode(true));dialog.dataset.printReady='true';status.textContent='พร้อมพิมพ์ '+data.rows.length+' รายการ · ลายเซ็น '+data.signatures.size+' รายการ';printButton.disabled=false}catch(error){if(active()){sheet.replaceChildren();status.textContent=(error.message||'โหลดรายงานไม่ครบ')+' · ยังไม่สามารถพิมพ์ได้ กรุณาลองใหม่'}}finally{busy=false;if(active())retry.disabled=false}}
 retry.onclick=load;printButton.onclick=async()=>{if(busy||!snapshot||!active())return;busy=true;delete dialog.dataset.printReady;printOutput.textContent='กำลังตรวจข้อมูลและสิทธิ์ก่อนพิมพ์';printButton.disabled=retry.disabled=true;status.textContent='กำลังตรวจสิทธิ์และข้อมูลก่อนพิมพ์…';try{if(!await verifySignatureReport(client,eventId,snapshot,active)||!active())return;printOutput.replaceChildren(sheet.cloneNode(true));await waitImages(printOutput);if(!active())return;dialog.dataset.printReady='true';print();status.textContent='เลือกเครื่องพิมพ์ หรือบันทึกเป็น PDF จากหน้าพิมพ์'}catch(error){if(active()){snapshot=null;delete dialog.dataset.printReady;printOutput.textContent='รายงานยังไม่พร้อมพิมพ์ กรุณาโหลดรายงานใหม่';sheet.replaceChildren();status.textContent=(error.message||'ตรวจรายงานไม่สำเร็จ')+' · กรุณาโหลดรายงานใหม่'}}finally{busy=false;if(active()){printButton.disabled=!snapshot;retry.disabled=false}}};await load();return dialog;
}
